import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"使用条款","description":"在 Mac 上使用 qDiff 的简要条款。","frontmatter":{"title":"使用条款","description":"在 Mac 上使用 qDiff 的简要条款。"},"headers":[],"relativePath":"zh-CN/terms/index.md","filePath":"zh-CN/terms/index.md","lastUpdated":1793948370000}'),o={name:"zh-CN/terms/index.md"};function l(n,a,h,d,p,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="使用条款" tabindex="-1">使用条款 <a class="header-anchor" href="#使用条款" aria-label="Permalink to &quot;使用条款&quot;">​</a></h1><p><em>更新日期：2026 年 11 月 6 日</em></p><p>感谢使用 qDiff。以下条款适用于应用和本网站。</p><h2 id="使用应用" tabindex="-1">使用应用 <a class="header-anchor" href="#使用应用" aria-label="Permalink to &quot;使用应用&quot;">​</a></h2><p>qDiff 用于比较和整理你自己的文件，家庭或工作场景都可以。你对自己选择打开的 文件负责，重要资料请自行保留备份。</p><p>应用按现状提供。我们努力让它稳定可靠，但无法保证永不中断或绝无差错，也不对 数据丢失承担责任。同步或删除文件之前，请先备份。</p><h2 id="免费版与购买" tabindex="-1">免费版与购买 <a class="header-anchor" href="#免费版与购买" aria-label="Permalink to &quot;免费版与购买&quot;">​</a></h2><p>所有比较功能免费。免费版在标签条上显示一个小标记；一次性购买可去掉它， 并包含以后新增的高级功能。没有订阅。</p><p>购买、退款与恢复购买由 Mac App Store 按 Apple 的条款和你的 Apple ID 处理， 我们不会收到你的支付信息。</p><h2 id="你的内容" tabindex="-1">你的内容 <a class="header-anchor" href="#你的内容" aria-label="Permalink to &quot;你的内容&quot;">​</a></h2><p>我们不主张对你的文件拥有任何权利，也不会收到这些文件，详见 <a href="./../privacy/">隐私政策</a>。</p><h2 id="本网站" tabindex="-1">本网站 <a class="header-anchor" href="#本网站" aria-label="Permalink to &quot;本网站&quot;">​</a></h2><p>网站内容仅供了解产品。随着 qDiff 更新，功能描述可能会调整。</p><h2 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h2><p>条款如有更新，会修改上面的日期。更新后继续使用 qDiff，即表示接受新条款。</p><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to &quot;联系&quot;">​</a></h2><p>有疑问，写信到 <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>。</p>',17)])])}const m=e(o,[["render",l]]);export{f as __pageData,m as default};
